package com.wizzadrds.theworldremembers.chronicle;
import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component; import java.util.*;
public final class ChronicleScreen extends Screen{private final List<String> lines;private int scroll;public ChronicleScreen(List<String> lines){super(Component.literal("The World Remembers — Chronicles"));this.lines=List.copyOf(lines);} @Override public void render(GuiGraphics g,int mx,int my,float delta){renderBackground(g,mx,my,delta);g.drawCenteredString(font,title,getWidth()/2,18,0xFFFFFF);int y=40;int end=Math.min(lines.size(),scroll+22);for(int i=scroll;i<end;i++){g.drawString(font,Component.literal(lines.get(i)),20,y,0xE0E0E0);y+=10;}g.drawString(font,Component.literal("↑/↓ scroll · Esc close"),20,getHeight()-20,0xAAAAAA);super.render(g,mx,my,delta);} @Override public boolean keyPressed(int key,int scan,int mods){if(key==265){scroll=Math.max(0,scroll-1);return true;}if(key==264){scroll=Math.min(Math.max(0,lines.size()-22),scroll+1);return true;}return super.keyPressed(key,scan,mods);} @Override public boolean mouseScrolled(double x,double y,double amount){scroll=(int)Math.max(0,Math.min(Math.max(0,lines.size()-22),scroll-(int)Math.signum(amount)));return true;}}
